{
  "00000000-0000-4000-8003-000000000001": {
    "name": "Sentinel KQL Rule",
    "metadata": {
      "uuid": "00000000-0000-4000-8003-000000000001",
      "schema": "rule::1.0",
      "version": 1,
      "created": "2026-01-01",
      "modified": "2026-01-02",
      "tlp": "clear"
    },
    "description": "Simulated Sentinel rule for CLI E2E corpus.\n",
    "status": "STAGING",
    "severity": "High",
    "techniques": [
      "T1059"
    ],
    "detection_model": "00000000-0000-4000-8002-000000000001",
    "response": {
      "alert_severity": "High"
    },
    "configurations": {
      "sentinel": {
        "enabled": true,
        "name": "Sentinel KQL Rule",
        "status": "STAGING",
        "query": "SecurityEvent\n| where EventID == 4688\n| take 1\n",
        "scheduling": {
          "frequency": "PT1H",
          "lookback": "PT2H"
        },
        "alert": {
          "title": "Sentinel KQL Rule",
          "suppression": false
        },
        "grouping": {
          "event": "SingleAlert",
          "alert": {
            "enabled": false
          }
        }
      }
    }
  },
  "00000000-0000-4000-8003-000000000002": {
    "name": "Defender KQL Rule",
    "metadata": {
      "uuid": "00000000-0000-4000-8003-000000000002",
      "schema": "rule::1.0",
      "version": 1,
      "created": "2026-01-01",
      "modified": "2026-01-02",
      "tlp": "clear"
    },
    "description": "Simulated Defender rule for CLI E2E corpus.\n",
    "status": "STAGING",
    "severity": "High",
    "techniques": [
      "T1059"
    ],
    "detection_model": "00000000-0000-4000-8002-000000000001",
    "response": {
      "alert_severity": "High"
    },
    "configurations": {
      "defender_for_endpoint": {
        "enabled": true,
        "name": "Defender KQL Rule",
        "status": "STAGING",
        "query": "DeviceProcessEvents\n| take 1\n",
        "scheduling": "1H",
        "alert": {
          "category": "Execution"
        },
        "impacted_entities": {
          "device": "device_id"
        },
        "scope": {
          "selection": "All"
        }
      }
    }
  },
  "00000000-0000-4000-8003-000000000003": {
    "name": "Splunk SPL Rule",
    "metadata": {
      "uuid": "00000000-0000-4000-8003-000000000003",
      "schema": "rule::1.0",
      "version": 1,
      "created": "2026-01-01",
      "modified": "2026-01-02",
      "tlp": "clear"
    },
    "description": "Simulated Splunk rule for CLI E2E corpus.\n",
    "status": "STAGING",
    "severity": "High",
    "techniques": [
      "T1059"
    ],
    "detection_model": "00000000-0000-4000-8002-000000000001",
    "response": {
      "alert_severity": "High"
    },
    "configurations": {
      "splunk": {
        "enabled": true,
        "name": "Splunk SPL Rule",
        "status": "STAGING",
        "query": "index=main | head 1",
        "scheduling": {
          "schedule": {
            "cron": "0 * * * *"
          }
        }
      }
    }
  },
  "00000000-0000-4000-8003-000000000004": {
    "name": "SentinelOne S1QL Rule",
    "metadata": {
      "uuid": "00000000-0000-4000-8003-000000000004",
      "schema": "rule::1.0",
      "version": 1,
      "created": "2026-01-01",
      "modified": "2026-01-02",
      "tlp": "clear"
    },
    "description": "Simulated SentinelOne rule for CLI E2E corpus.\n",
    "status": "STAGING",
    "severity": "High",
    "techniques": [
      "T1059"
    ],
    "detection_model": "00000000-0000-4000-8002-000000000001",
    "response": {
      "alert_severity": "High"
    },
    "configurations": {
      "sentinel_one": {
        "enabled": true,
        "name": "SentinelOne S1QL Rule",
        "status": "STAGING",
        "condition": {
          "type": "Correlation",
          "correlation": {
            "entity": "host",
            "match_in_order": true,
            "time_window": "1h",
            "sub_queries": [
              {
                "query": "EventType = \"Process Create\"",
                "matches_required": 1
              }
            ]
          }
        },
        "response": {
          "treat_as_threat": "Malicious",
          "network_quarantine": false
        }
      }
    }
  },
  "00000000-0000-4000-8003-000000000005": {
    "name": "Carbon Black Lucene Rule",
    "metadata": {
      "uuid": "00000000-0000-4000-8003-000000000005",
      "schema": "rule::1.0",
      "version": 1,
      "created": "2026-01-01",
      "modified": "2026-01-02",
      "tlp": "clear"
    },
    "description": "Simulated Carbon Black rule for CLI E2E corpus.\n",
    "status": "STAGING",
    "severity": "High",
    "techniques": [
      "T1059"
    ],
    "detection_model": "00000000-0000-4000-8002-000000000001",
    "response": {
      "alert_severity": "High"
    },
    "configurations": {
      "carbon_black_cloud": {
        "enabled": true,
        "name": "Carbon Black Lucene Rule",
        "status": "STAGING",
        "query": "process_name:cmd.exe"
      }
    }
  },
  "00000000-0000-4000-8003-000000000006": {
