      "version": 1,
      "created": "2026-01-01",
      "modified": "2026-01-02",
      "tlp": "clear"
    },
    "description": "Simulated CrowdStrike rule for CLI E2E corpus (deploy-only).\n",
    "status": "STAGING",
    "severity": "High",
    "techniques": [
      "T1059"
    ],
    "detection_model": "00000000-0000-4000-8002-000000000001",
    "response": {
      "alert_severity": "High"
    },
    "configurations": {
      "crowdstrike": {
        "enabled": true,
        "name": "CrowdStrike Deploy Rule",
        "status": "STAGING",
        "query": "index=main",
        "details": {
          "trigger": "event",
          "outcome": "detection"
        },
        "schedule": {
          "frequency": "1h",
