  "00000000-0000-4000-8003-000000000007": {
    "name": "HarfangLab Deploy Rule",
    "metadata": {
      "uuid": "00000000-0000-4000-8003-000000000007",
      "schema": "rule::1.0",
      "version": 1,
      "created": "2026-01-01",
      "modified": "2026-01-02",
      "tlp": "clear"
    },
    "description": "Simulated HarfangLab rule for CLI E2E corpus (deploy-only).\n",
    "status": "STAGING",
    "severity": "High",
    "techniques": [
      "T1059"
    ],
    "detection_model": "00000000-0000-4000-8002-000000000001",
    "response": {
      "alert_severity": "High"
    },
    "configurations": {
      "harfanglab": {
        "enabled": true,
        "name": "HarfangLab Deploy Rule",
        "status": "STAGING",
        "action": "Alert",
        "sigma": {
          "logsource": {
            "category": "process_creation",
            "product": "windows"
          },
          "selections": [
            {
              "name": "selection",
              "field": "Image",
              "value": "cmd.exe"
            }
          ],
          "condition": "selection"
        }
      }
    }
  },
  "00000000-0000-4000-8003-000000000008": {
    "name": "Staging Promote Rule",
    "metadata": {
      "uuid": "00000000-0000-4000-8003-000000000008",
      "schema": "rule::1.0",
      "version": 2,
      "created": "2026-01-01",
      "modified": "2026-01-03",
      "tlp": "clear"
    },
    "description": "Rule with higher metadata.version for mutate/promote E2E tests.\n",
    "status": "STAGING",
    "severity": "High",
    "techniques": [
      "T1059"
    ],
    "detection_model": "00000000-0000-4000-8002-000000000001",
    "response": {
      "alert_severity": "Medium"
    },
    "configurations": {
      "sentinel": {
        "enabled": true,
        "name": "Staging Promote Rule",
        "status": "STAGING",
        "query": "SecurityEvent | take 1\n",
        "scheduling": {
          "frequency": "PT1H",
          "lookback": "PT2H"
        },
        "alert": {
          "title": "Staging Promote Rule",
          "suppression": false
        },
        "grouping": {
          "event": "SingleAlert",
          "alert": {
            "enabled": false
          }
        }
      }
    }
  },
  "00000000-0000-4000-8003-000000000009": {
    "name": "Elastic KQL Rule",
    "metadata": {
      "uuid": "00000000-0000-4000-8003-000000000009",
      "schema": "rule::1.0",
      "version": 1,
      "created": "2026-01-01",
      "modified": "2026-01-02",
      "tlp": "clear"
    },
    "description": "Simulated Elastic rule for CLI E2E corpus.\n",
    "status": "STAGING",
    "severity": "High",
    "techniques": [
      "T1059"
    ],
    "detection_model": "00000000-0000-4000-8002-000000000001",
    "response": {
      "alert_severity": "High"
    },
    "configurations": {
      "elastic": {
        "enabled": true,
        "schema": "platform::elastic::1.0",
        "status": "STAGING",
        "type": "query",
        "language": "kuery",
        "query": "process.name: \"powershell.exe\"\n",
        "index": [
          "logs-*"
        ],
        "scheduling": {
          "interval": "5m",
          "lookback": "1m"
        }
      }
    }
  },
  "00000000-0000-4000-8003-0000005d1a90": {
    "name": "Sysdig Falco Rule",
    "metadata": {
      "uuid": "00000000-0000-4000-8003-0000005d1a90",
      "schema": "rule::1.0",
      "version": 1,
      "created": "2026-01-01",
      "modified": "2026-01-02",
      "tlp": "clear"
    },
    "description": "Simulated Sysdig Secure Falco rule for CLI E2E corpus: a shell spawned in\na container.\n",
    "status": "STAGING",
    "severity": "Medium",
    "techniques": [
      "T1059.004"
    ],
    "detection_model": "00000000-0000-4000-8002-000000000001",
    "response": {
      "alert_severity": "Medium"
    },
    "configurations": {
      "sysdig": {
        "enabled": true,
        "schema": "platform::sysdig::1.0",
        "status": "STAGING",
        "condition": "spawned_process and container and proc.name in (corpus_shells)\n",
        "lists": [
          {
            "name": "corpus_shells",
            "items": [
              "bash",
              "sh",
              "zsh"
            ]
          }
        ],
        "tags": [
          "container",
          "shell"
        ]
      }
    }
  }
}
